  public static final PhonAdapter<TerminalConnectRequest> ADAPTER = new PhonAdapter<>() {
    @Override public SchemaClosure schema() { return SCHEMA_CLOSURE; }
    @Override public void encode(PhonEncoder encoder, TerminalConnectRequest value) throws PhonException {
      encoder.writeString(value.endpoint());
      encoder.writeU16(value.requestedWidth());
      encoder.writeU16(value.requestedHeight());
      encoder.writeAdapted(TerminalSurfaceMetrics.ADAPTER, value.surface());
      encoder.writeAdapted(TerminalCapabilities.ADAPTER, value.capabilities());
      encoder.writeI64(value.clientSequence());
      encoder.writeString(value.correlationId());
      encoder.writeBool(value.tuningPresent());
      encoder.writeAdapted(TerminalTuningRequest.ADAPTER, value.tuning());
    }
    @Override public TerminalConnectRequest decode(PhonDecoder decoder) throws PhonException { return new TerminalConnectRequest(decoder.readString(), decoder.readU16(), decoder.readU16(), decoder.readAdapted(TerminalSurfaceMetrics.ADAPTER), decoder.readAdapted(TerminalCapabilities.ADAPTER), decoder.readI64(), decoder.readString(), decoder.readBool(), decoder.readAdapted(TerminalTuningRequest.ADAPTER)); }
  };

  @Override public boolean equals(Object other) {
    if (!(other instanceof TerminalConnectRequest that)) return false;
    return Objects.deepEquals(endpoint, that.endpoint) && Objects.deepEquals(requestedWidth, that.requestedWidth) && Objects.deepEquals(requestedHeight, that.requestedHeight) && Objects.deepEquals(surface, that.surface) && Objects.deepEquals(capabilities, that.capabilities) && Objects.deepEquals(clientSequence, that.clientSequence) && Objects.deepEquals(correlationId, that.correlationId) && Objects.deepEquals(tuningPresent, that.tuningPresent) && Objects.deepEquals(tuning, that.tuning);
  }
  @Override public int hashCode() { return Objects.hash(endpoint, requestedWidth, requestedHeight, surface, capabilities, clientSequence, correlationId, tuningPresent, tuning); }
  @Override public String toString() { return "TerminalConnectRequest" + java.util.List.of(endpoint, requestedWidth, requestedHeight, surface, capabilities, clientSequence, correlationId, tuningPresent, tuning); }
